5	namespace chatai_admin.Filter
6	{
7	    public class IpWhiteListFilter : IAsyncActionFilter
8	    {
9	        private readonly IConfiguration _config;
10	        private readonly ILogger<IpWhiteListFilter> _logger;
11	
12	        public IpWhiteListFilter(IConfiguration config, ILogger<IpWhiteListFilter> logger)
13	        {
14	            _config = config;
15	            _logger = logger;
16	        }
17	
18	        public async Task OnActionExecutionAsync(ActionExecutingContext context, ActionExecutionDelegate next)
19	        {
20	            var whiteList = _config.GetSection("WhiteIpList").Get<string[]>() ?? Array.Empty<string>();
21	            var remoteIp = GetClientIp(context.HttpContext);
22	
23	#if !DEBUG
24	
25	            if (remoteIp == null || !IsAllowed(remoteIp, whiteList))
26	            {
27	                _logger.LogError("拒絕 IP {IP} 存取 {Path}", remoteIp, context.HttpContext.Request.Path);
28	                context.Result = new StatusCodeResult(StatusCodes.Status403Forbidden);
29	                return;
30	            }
31	
32	#endif
33	
34	            await next();
35	        }
36	
37	        private IPAddress? GetClientIp(HttpContext httpContext)
38	        {
39	            // 如果有 Proxy，優先取 X-Forwarded-For
40	            var header = httpContext.Request.Headers["X-Forwarded-For"].FirstOrDefault();
41	            if (!string.IsNullOrWhiteSpace(header))
42	            {
43	                var first = header.Split(',').First().Trim();
44	                if (IPAddress.TryParse(first, out var forwardedIp))
45	                    return forwardedIp;
46	            }
47	
48	            return httpContext.Connection.RemoteIpAddress;
49	        }
50	
51	        private bool IsAllowed(IPAddress ip, string[] rules)
52	        {
53	            foreach (var rule in rules)
54	            {
55	                if (TryParseCidr(rule, out var network, out var prefixLen))
56	                {
57	                    if (IsInCidr(ip, network!, prefixLen)) return true;
58	                }
59	                else if (IPAddress.TryParse(rule, out var exact))
60	                {
61	                    if (exact.Equals(ip)) return true;
62	                }
63	            }
64	            return false;
65	        }
66	
67	        private static bool TryParseCidr(string input, out IPAddress? network, out int prefixLength)
68	        {
69	            network = null;
70	            prefixLength = 0;
71	            var parts = input.Split('/');
72	            if (parts.Length != 2) return false;
73	            if (!IPAddress.TryParse(parts[0], out network)) return false;
74	            if (!int.TryParse(parts[1], out prefixLength)) return false;
75	            return true;
76	        }
77	
78	        private static bool IsInCidr(IPAddress ip, IPAddress network, int prefixLength)
79	        {
80	            if (ip.AddressFamily != network.AddressFamily) return false;
81	            var ipBytes = ip.GetAddressBytes();
82	            var netBytes = network.GetAddressBytes();
83	            int fullBytes = prefixLength / 8;
84	            int bits = prefixLength % 8;
85	
86	            for (int i = 0; i < fullBytes; i++)
87	            {
88	                if (ipBytes[i] != netBytes[i]) return false;
89	            }
90	
91	            if (bits == 0) return true;
92	
93	            int mask = 0xFF << (8 - bits) & 0xFF;
94	            return (ipBytes[fullBytes] & mask) == (netBytes[fullBytes] & mask);
95	        }
96	    }
97	}
