27	        public void OnActionExecuting(ActionExecutingContext context)
28	        {
29	            //if (!IsJWTOnly(context)) return;
30	
31	            if (IsAllowAnonymous(context)) return;
32	
33	            if (!context.HttpContext.Request.Headers.TryGetValue("Authorization", out var encryptedSignature))
34	                throw new CustomException("缺少 Authorization Header.");
35	
36	            var authToken = encryptedSignature.ToNullString();
37	            if (string.IsNullOrEmpty(authToken) || !authToken.StartsWith("Bearer"))
38	                throw new CustomException("Invalid Authorization Header");
39	
40	            // 驗證 Token 是否有效
41	            if (!JWTHelper.ValidateToken(authToken, out var principal))
42	                throw new CustomException("Authorization驗證失敗");
43	
44	            var jwtInfo = JWTHelper.GetJwtInfo(authToken);
45	            if (!_requiredAdminAccountType.Any(x => x == jwtInfo.accountTypeCode) || !_appSettingConfig.AdminUsers!.Any(x => x == jwtInfo.accountName))
46	                throw new CustomException("沒有權限");
47	        }
