143	        [HttpGet]
144	        [ValidateRequestToken]
145	        public IActionResult Download([FromQuery] string fileName, [FromQuery] string subfolder = "", [FromQuery] bool isView = false)
146	        {
147	            if (string.IsNullOrEmpty(fileName))
148	                throw new CustomException("未指定檔案名稱");
149	
150	            var folder = string.IsNullOrEmpty(subfolder) ? _baseFolder : Path.Combine(_baseFolder, subfolder);
151	            var filePath = Path.Combine(folder, fileName);
152	            if (!System.IO.File.Exists(filePath))
153	                throw new CustomException("檔案不存在");
154	
155	            var ext = Path.GetExtension(fileName).ToLower();
156	            var contentType = ext switch
157	            {
158	                ".pdf" => "application/pdf",
159	                ".md" => "text/markdown",
160	                ".xls" => "application/vnd.ms-excel",
161	                ".xlsx" => "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
162	                ".csv" => "text/csv; charset=utf-8",
163	                ".docx" => "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
164	                _ => "application/octet-stream"
165	            };
166	
167	            byte[] bytes;
168	            if (ext == ".csv")
169	            {
170	                // 偵測編碼
171	                CharsetDetector detector = new CharsetDetector();
172	                using (var fs = System.IO.File.OpenRead(filePath))
173	                {
174	                    detector.Feed(fs);
175	                    detector.DataEnd();
176	                }
177	                var encoding = detector.Charset != null ? Encoding.GetEncoding(detector.Charset) : Encoding.UTF8;
178	                var lines = System.IO.File.ReadAllLines(filePath, encoding);
179	                bytes = Encoding.UTF8.GetBytes(string.Join(Environment.NewLine, lines));
180	            }
181	            else
182	            {
183	                bytes = System.IO.File.ReadAllBytes(filePath);
184	            }
185	
186	            if (isView)
187	                return File(bytes, contentType);
188	            else
189	                return File(bytes, contentType, fileName);
190	        }
